55	  localparam VAL_DBG_DEST_ADDR = 32'hfedcba98;
56	  localparam VAL_DBG_STATUS = 12'ha5;
57	  localparam VAL_DBG_IDS0 = 32'h01234567;
58	  localparam VAL_DBG_IDS1 = 32'h89abcdef;
59	
60	  localparam AW = 11;
61	  localparam NUM_REGS = 'h200;
62	
63	  wire s_axi_aclk = clk;
64	  wire s_axi_aresetn = ~reset;
65	
66	  reg s_axi_awvalid = 1'b0;
67	  reg s_axi_wvalid = 1'b0;
68	  reg [AW-1:0] s_axi_awaddr = 'h00;
69	  reg [31:0] s_axi_wdata = 'h00;
70	  wire [1:0] s_axi_bresp;
71	  wire s_axi_awready;
72	  wire s_axi_wready;
73	  wire s_axi_bready = 1'b1;
74	  wire [3:0] s_axi_wstrb = 4'b1111;
75	  wire [2:0] s_axi_awprot = 3'b000;
76	  wire [2:0] s_axi_arprot = 3'b000;
77	  wire [1:0] s_axi_rresp;
78	  wire [31:0] s_axi_rdata;
79	
80	  task write_reg;
81	  input [31:0] addr;
82	  input [31:0] value;
83	  begin
84	    @(posedge s_axi_aclk)
85	    s_axi_awvalid <= 1'b1;
86	    s_axi_wvalid <= 1'b1;
87	    s_axi_awaddr <= addr;
88	    s_axi_wdata <= value;
89	    @(posedge s_axi_aclk)
90	    while (s_axi_awvalid || s_axi_wvalid) begin
91	      @(posedge s_axi_aclk)
92	      if (s_axi_awready)
93	        s_axi_awvalid <= 1'b0;
94	      if (s_axi_wready)
95	        s_axi_wvalid <= 1'b0;
96	    end
97	  end
98	  endtask
99	
100	  reg [31:0] expected_reg_mem[0:NUM_REGS-1];
101	
102	  reg [AW-1:0] s_axi_araddr = 'h0;
103	  reg s_axi_arvalid = 'h0;
104	  reg s_axi_rready = 'h0;
105	  wire s_axi_arready;
106	  wire s_axi_rvalid;
107	
108	  task read_reg;
109	  input [31:0] addr;
110	  output [31:0] value;
111	  begin
112	    s_axi_arvalid <= 1'b1;
113	    s_axi_araddr <= addr;
114	    s_axi_rready <= 1'b1;
115	    @(posedge s_axi_aclk) #0;
116	    while (s_axi_arvalid) begin
117	      if (s_axi_arready == 1'b1) begin
118	        s_axi_arvalid <= 1'b0;
119	      end
120	      @(posedge s_axi_aclk) #0;
121	    end
122	
123	    while (s_axi_rready) begin
124	      if (s_axi_rvalid == 1'b1) begin
125	        value <= s_axi_rdata;
126	        s_axi_rready <= 1'b0;
127	      end
128	      @(posedge s_axi_aclk) #0;
129	    end
130	  end
131	  endtask
132	
133	  task read_reg_check;
134	  input [31:0] addr;
135	  output match;
136	  reg [31:0] value;
137	  reg [31:0] expected;
138	  input [255:0] message;
139	  begin
140	    read_reg(addr, value);
141	    expected = expected_reg_mem[addr[11:2]];
142	    match <= value === expected;
143	    if (value !== expected) begin
144	      $display("%0s: Register mismatch for %x. Expected %x, got %x",
145	        message, addr, expected, value);
146	    end
147	  end
148	  endtask
149	
150	  reg read_match = 1'b1;
151	
152	  always @(posedge clk) begin
153	    if (read_match == 1'b0) begin
154	      failed <= 1'b1;
155	    end
156	  end
157	
158	  task set_reset_reg_value;
159	  input [31:0] addr;
160	  input [31:0] value;
161	  begin
162	    expected_reg_mem[addr[AW-1:2]] <= value;
163	  end
164	  endtask
165	
166	  task initialize_expected_reg_mem;
167	  integer i;
168	  begin
169	    for (i = 0; i < NUM_REGS; i = i + 1)
170	      expected_reg_mem[i] <= 'h00;
171	    /* Non zero power-on-reset values */
172	    set_reset_reg_value('h00, 32'h00040565); /* PCORE version register */
173	    set_reset_reg_value('h0c, 32'h444d4143); /* PCORE magic register */
174	    set_reset_reg_value('h10, 32'h38072101); /* Interface Description*/
175	    set_reset_reg_value('h80, 'h3); /* IRQ mask */
176	
177	    set_reset_reg_value('h40c, 'h3); /* Flags */
178	    set_reset_reg_value('h418, LENGTH_ALIGN_MASK); /* Length alignment */
179	
180	    set_reset_reg_value('h434, VAL_DBG_DEST_ADDR);
181	    set_reset_reg_value('h438, VAL_DBG_SRC_ADDR);
182	    set_reset_reg_value('h43c, VAL_DBG_STATUS);
183	    set_reset_reg_value('h440, VAL_DBG_IDS0);
184	    set_reset_reg_value('h444, VAL_DBG_IDS1);
185	  end
186	  endtask
187	
188	  task check_all_registers;
189	  input [255:0] message;
190	  integer i;
191	  begin
192	    for (i = 0; i < NUM_REGS*4; i = i + 4) begin
193	      read_reg_check(i, read_match, message);
194	    end
195	  end
196	  endtask
197	
198	  task write_reg_and_update;
199	  input [31:0] addr;
200	  input [31:0] value;
201	  integer i;
202	  begin
203	    write_reg(addr, value);
204	    expected_reg_mem[addr[AW-1:2]] <= value;
205	  end
206	  endtask
207	
208	  task invert_register;
209	  input [31:0] addr;
210	  reg [31:0] value;
211	  begin
212	    read_reg(addr, value);
213	    write_reg(addr, ~value);
214	  end
215	  endtask
216	
217	  task invert_all_registers;
218	  integer i;
219	  begin
220	    for (i = 0; i < NUM_REGS*4; i = i + 4) begin
221	      invert_register(i);
222	    end
223	  end
224	  endtask
225	
226	  reg request_ready = 1'b0;
227	  wire [31:BYTES_PER_BEAT] request_dest_address;
228	  wire [31:BYTES_PER_BEAT] request_src_address;
229	  wire [DMA_LENGTH_WIDTH-1:0] request_x_length;
