276	    write_reg_and_update('h41c, LENGTH_MASK);
277	    write_reg_and_update('h420, STRIDE_MASK);
278	    write_reg_and_update('h424, STRIDE_MASK);
279	
280	    check_all_registers("Transfer setup 1");
281	
