295	    write_reg_and_update('h408, 'h01);
296	    set_reset_reg_value('h428, 32'h00000000);
297	    set_reset_reg_value('h448, 24'h000000);
298	    set_reset_reg_value('h44c, 32'hxxxxxxxx);
299	    set_reset_reg_value('h450, 2'bX);
300	
301	    check_all_registers("Transfer submitted");
