311	
312	    /* Tansfer pending */
313	    set_reset_reg_value('h408, 'h00);
314	    set_reset_reg_value('h428, 32'h80000000);
315	    set_reset_reg_value('h448, 24'h000080);
316	    set_reset_reg_value('h44c, 32'h00000080);
317	    set_reset_reg_value('h450, 'h0);
318	    check_all_registers("Transfer accepted");
319	
320	    @(posedge clk) response_eot <= 1'b1;
321	    @(posedge clk) response_eot <= 1'b0;
322	
323	    /* Interrupt registers */
324	    set_reset_reg_value('h84, 'h01);
325	    set_reset_reg_value('h88, 'h01);
326	
327	    set_reset_reg_value('h428, 'h00);
328	    set_reset_reg_value('h42c, 'h00);
329	    set_reset_reg_value('h44c, 32'h00000080);
330	    set_reset_reg_value('h450, 'h0);
331	    set_reset_reg_value('h448, 24'h000080);
332	
333	    check_all_registers("Transfer completed");
334	
335	    /* Clear interrupts */
336	    write_reg('h84, 'h01);
337	    set_reset_reg_value('h84, 'h00);
338	    set_reset_reg_value('h88, 'h00);
339	
340	    check_all_registers("Clear interrupts 1");
341	
342	    write_reg('h84, 'h02);
343	    set_reset_reg_value('h84, 'h00);
344	    set_reset_reg_value('h88, 'h00);
345	
346	    check_all_registers("Clear interrupts 2");
347	
348	    /* Check that reset works for all registers */
349	    do_trigger_reset();
350	    initialize_expected_reg_mem();
351	    write_reg_and_update('h40c, 'h00);
352	    set_reset_reg_value('h44c, 32'h00000080);
353	    check_all_registers("Reset 1");
354	    invert_all_registers();
355	    do_trigger_reset();
356	    write_reg_and_update('h40c, 'h00);
357	    set_reset_reg_value('h44c, 32'h00000080);
358	    check_all_registers("Reset 2");
359	  end
360	
